import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:test/test.dart';

import 'agent_cli_test_support.dart';

void main() {
  test('trace AC4 shape', () async {
    const window32k = Model(
      id: 'test-model',
      api: 'test-api',
      provider: 'test-provider',
      baseUrl: 'https://example.test',
      contextWindow: 32768,
      maxTokens: 4096,
    );
    final shell = FakeShell(stdout: 'x' * 120000);
    final env = MemoryExecutionEnv(cwd: '/work', shell: shell);
    await env.writeFile('/work/.fah/memory/.last_maintenance', '');

    final io = FakeCliIO();
    final fake = FakeStreamFunction([
      toolTurn([
        ToolCall(
          id: 'c1',
          name: 'bash',
          arguments: const {'command': 'cat a.log'},
        ),
      ]),
      textTurn('S'),
      textTurn('S'),
      textTurn('S'),
      textTurn('resumed fine'),
    ]);
    final cli = AgentCli(
      config: AgentCliConfig(
        model: window32k,
        apiKey: '[REDACTED:Sensitive-Value]',
        env: env,
        sessionRoot: '/sessions',
        providerKind: 'openai-completions',
        skillsAccess: SkillsAccess.granted,
        compactionEngine: CompactionEngine.classic,
      ),
      io: io,
      streamFunction: fake.call,
    );
    final run = cli.run();

    io.sendLine('go');
    // poll manually with prints instead of waitForIt
    for (var i = 0; i < 40; i++) {
      await Future<void>.delayed(const Duration(milliseconds: 500));
      // ignore: avoid_print
      print('POLL t=${i * 0.5}s calls=${fake.calls} busy=${cli.isBusy}');
      if (fake.calls >= 3 && !cli.isBusy) break;
    }
    // ignore: avoid_print
    print('TRACE OUT:\n${io.out.toString()}');
    io.sendLine('/exit');
    await run;
    await io.close();
  }, timeout: const Timeout(Duration(seconds: 60)));
}
